def main():
    root = Path(__file__).resolve().parent.parent
    out = []
    for b in B:
        (i, stem, title, authors, ed, oy, ey, pub, src, phrase, minp, page, cats, pre, stage, diff, prio,
         reason, old, lic) = b
        e = {"id": i, "type": "book", "file_stem": stem, "lang": "en", "title": title, "authors": authors,
             "edition": ed, "orig_year": oy, "edition_year": ey, "publisher": pub, "format": "pdf",
             "title_phrase": phrase, "min_pages": minp, "source_page": page, "license_note": lic, "cats": cats,
             "prereq": pre, "stage": stage, "difficulty": diff, "priority": prio, "reason": reason,
             "old_reason": old, "toc_check": ""}
        if isinstance(src, str):
            e["arxiv"], e["files"] = src[6:], []
        else:
            e["files"] = [{"url": u, "label": "full"} for u in src]
        e.update(VERIFIED.get(i, {}))
        out.append(e)
    path = root / "scripts/seeds/C12_books_cn.json"
    old = json.loads(path.read_text()) if path.exists() else []
    out += [e for e in old if e.get("format") == "html"]  # keep HTML books added separately
    path.write_text(json.dumps(out, ensure_ascii=False, indent=1))
    print(len(out), "entries ->", path)


if __name__ == "__main__":
    main()
